import growthConfig from './config-check.mjs';
import dedupIntegrity from './dedup-integrity.mjs';

// Opt into the growth lifecycle: a repo declaring grow_with_claudinite contributes its
// hard-won lessons up to the Claudinite canon and prunes them back out once the canon
// owns them. This pack carries the REPO-side stages — extract, dedup, the weekly local
// pack discovery, and the prose-to-checks sweep — as scheduled tasks under this pack's
// own `tasks/`, discovered by the scheduler's filesystem scan
// (engine/scheduler/discover.mjs), so none of them is declared here. The central
// promote stage — lifting portable lessons up into the shared canon — is a home-only
// duty that runs canon-side, outside this pack; its precondition targets exactly the
// members that declare THIS pack, minus any member whose entry sets config.promote:
// false (the promotion opt-out; extraction and dedup stay local either way).
//
// The pack also owns the CONVERSATION lifecycle: merge-to-main's capture step pushes
// each merged session's conversation onto the orphan conversation-logs branch
// (capture-log.mjs, in-session — it needs the live transcript), and the
// conversation-extract task (tasks/conversation-extract/) mines those pushed
// logs with growth-extract's access model — the logs branch is in the repo, so reading
// it, committing lessons to local packs, and pruning aged logs are plain local git;
// only posting the short summary behind each extracted rule on its issue uses the
// GitHub MCP tools — pruning logs past config.retention_days.
//
// growth-discover-packs is the weekly LOCAL pack-discovery reflection: the repo
// manifests its own stack, notices project-specific knowledge no canon pack homes,
// and authors a local pack for it under its own `.claudinite/local/packs/`.
//
// A declared pack (no fingerprint), seeded like tidy-repo: --init seeds it into every
// new repo, the one-time grow-with-claudinite-seed migration seeds the existing fleet,
// and baselining never re-adds it — so removing it is a durable opt-out.
export default {
  id: 'grow_with_claudinite',
  detect: null,
  marker: null,
  seededByDefault: true,
  prose: null,
  rules: [growthConfig, dedupIntegrity],
  questions: [{
    id: 'retention',
    prompt: 'How many days should a captured conversation log stay on the conversation-logs branch before the conversation-extract retention prune deletes it? The floor is the rethink window — extraction wants ~a week of hindsight; 10 is the recommended value.',
    distill: 'set config.retention_days on this entry to the agreed positive integer; until it is set, the prune deletes nothing (capture-only adoption)',
  }],
};
=== sheepdog/pack.mjs
// The sheepdog pack: a MARKER + config. Declaring it on a repo makes that repo the
// fleet ENFORCER — the one that covers and maintains every repo under an owner. It's
// opt-in (a dedicated sheepdog repo declares it; NOT seeded by --init).
//
// The pack is thin: prose (RULES.md), the config schema (the pack entry's config =
// { owner, kind, exclude, canonRepo, staleDays }), and the account-spanning sweeps
// that ARE the cross-repo reach the pack adds — each with the ordinary agentless
// scheduled task that runs it (the sweep IS its agent_preprocessing, and its
// required_secrets is what asks the repo for FLEET_GITHUB_TOKEN):
//
//   tasks/fleet-census/check-fleet-coverage.mjs      is a repo a MEMBER?
//   tasks/fleet-freshness/check-fleet-freshness.mjs  is a member KEEPING UP?
//
// Each sweep lives INSIDE its task's folder — nothing outside that task uses it.
// The pack root holds only what both need: fleet-api.mjs (the cross-repo REST
// primitives) and fleet-config.mjs (the one reader of this pack entry's config).
//
// The second exists because per-project scheduling made every member maintain
// itself and, in doing so, removed the last thing that looked at a member from the
// outside — self-maintenance cannot detect its own absence.
//
// No workflow of its own: preprocessing
// runs Action-side inside the repo's one scheduler workflow, where that secret is
// already reachable. Everything else — the SCHEDULER (engine/scheduler/run.mjs), the
// orchestrator/daily-run, the task engine (engine/scheduler/), scheduling — is CORE and
// pack-agnostic; the planner never runs, dispatches, or depends on these sweeps.
export default {
  id: 'sheepdog',
  detect: null,
  marker: null,
  prose: 'RULES.md',
  rules: [],
};
=== fleet-api
// The sheepdog census's cross-repo GitHub REST client. Dependency-free (global
// fetch, Node 20+). This is the ONE place a Claudinite process talks GitHub over
// raw REST with a token, and it is deliberately confined to the census — the
// account-spanning coverage audit that must enumerate EVERY repo the owner owns
// (`/user/repos`), which a session-scoped connection structurally cannot see. The
// census runs Action-side as the fleet-census task's preprocessing, with a
// fine-grained PAT; nothing in the daily-maintenance process imports this (that
// process is MCP-native and carries no REST client). It knows nothing about any
// specific pack: it is the generic "talk to many repos" layer, no more.

const API = 'https://api.github.com';

export function makeGh(token) {
  return async function gh(path, { method = 'GET', body } = {}) {
    const res = await fetch(`${API}${path}`, {
      method,
      headers: {
        Authorization: `Bearer ${token}`,
        Accept: 'application/vnd.github+json',
        'X-GitHub-Api-Version': '2022-11-28',
        ...(body ? { 'Content-Type': 'application/json' } : {}),
      },
      body: body ? JSON.stringify(body) : undefined,
    });
    const text = await res.text();
    let json = null;
    try { json = text ? JSON.parse(text) : null; } catch { /* non-JSON body */ }
    return { status: res.status, json };
  };
}

export async function paged(gh, path) {
  const sep = path.includes('?') ? '&' : '?';
  const all = [];
  for (let page = 1; ; page += 1) {
    const { status, json } = await gh(`${path}${sep}per_page=100&page=${page}`);
    if (status !== 200 || !Array.isArray(json)) {
      throw new Error(`GET ${path} page ${page} failed with status ${status}`);
    }
    all.push(...json);
    if (json.length < 100) return all;
  }
}

// --- the enforcer repo's own issue surface -----------------------------------
// Both sweeps this pack runs (coverage and freshness) converge a labelled issue
// per finding IN THE ENFORCER REPO. The label ensure and the labelled-issue read
// are identical between them — only the open/close POLICY differs, and that stays
// in each sweep, where its semantics are legible. These two are the shared floor.

// Idempotent: 422 is "already exists", which is the state we wanted.
export async function ensureLabel(gh, repo, name, { color, description }) {
  const { status } = await gh(`/repos/${repo}/labels`, { method: 'POST', body: { name, color, description } });
  if (status !== 201 && status !== 422) throw new Error(`creating label ${name} returned ${status}`);
}

// Every issue ever carrying the label, open and closed, PRs filtered out — a
// sweep needs the closed ones to tell "converged" from "never opened", and to
// honour a close the owner made deliberately.
export async function labeledIssues(gh, repo, label) {
  const all = (await paged(gh, `/repos/${repo}/issues?labels=${label}&state=all`)).filter((i) => !i.pull_request);
  return { open: all.filter((i) => i.state === 'open'), closed: all.filter((i) => i.state === 'closed') };
}

// 200 → true, 404 → false, anything else → error (the caller decides what an
// indeterminate result means).
export async function fileExists(gh, fullName, path) {
  const { status } = await gh(`/repos/${fullName}/contents/${path}`);
  if (status === 200) return true;
  if (status === 404) return false;
  throw new Error(`marker check ${fullName}:${path} returned ${status}`);
}

// Does this repo mount Claudinite? (Method B sync hook / legacy gitkeep / Method A
// submodule.) The structural "is this a covered member" test, shared by the planner
// (which repos to plan over) and the census (which repos are uncovered).
export async function isCovered(gh, fullName) {
  // The tracked declaration file is THE membership signal — the one file every
  // member carries whatever its mount shape (the engine can't run without it,
  // and baselining backfills it nightly), and the only shape the planner can
  // plan for at all (activePacks is read from it). A mount marker WITHOUT a
  // declaration is a half-adoption that must classify as uncovered — the census
  // then opens an adoption issue and it heals loudly, instead of rotting as a
  // "covered" repo no task ever runs on. (vendoring/DESIGN.md)
  return fileExists(gh, fullName, '.claudinite-checks.json');
}
=== fleet-config
// The sheepdog pack's fleet CONFIG reader — the one parser for the enforcer repo's
// `sheepdog` pack entry.
//
// It lives at the pack root, not inside a task, because BOTH sweeps read the same
// entry: the census (tasks/fleet-census/) needs `owner` and `exclude`, the freshness
// sweep (tasks/fleet-freshness/) needs those plus `canonRepo` and `staleDays`. A
// second reader would be a second place for the owner/exclude semantics to drift —
// and this is what the file-placement skill calls lifting a shared dependency to the
// nearest common ancestor: distance 2 from each task instead of one task reaching
// into the other's folder.

// The sheepdog repo's .claudinite-checks.json carries, on its sheepdog pack entry:
//   { "id": "sheepdog", "config": { owner: "missingbulb", kind: "user", exclude: ["owner/repo", ...],
//                                   canonRepo: "missingbulb/Claudinite", staleDays: 14 } }
// owner is who to cover (default: the sheepdog repo's own owner); exclude is the repos
// deliberately kept out (a full owner/name each, lowercased). canonRepo and staleDays
// are the freshness sweep's two knobs and both default, so an existing config keeps
// working untouched. Callers read the home repo's file raw (fetched over the API, no
// engine on hand), so this resolves the entry itself — legacy top-level
// packConfig.sheepdog stays readable underneath until the `pack-entry-config` baseline
// migration retires (drop the fallback then). A missing config is an unreadable
// config: throw — absence is not consent to cover everything.
export function parseSheepdogConfig(cfg, home) {
  const entry = (Array.isArray(cfg?.packs) ? cfg.packs : []).find((e) => e?.id === 'sheepdog');
  const sd = entry?.config ?? cfg?.packConfig?.sheepdog;
  if (!sd || typeof sd !== 'object') {
    throw new Error(`the sheepdog repo ${home} declares no sheepdog config { owner, exclude } (on the pack entry or legacy packConfig.sheepdog) — nothing to cover`);
  }
  const owner = String(sd.owner ?? home.split('/')[0]).toLowerCase();
  const exclude = new Set((Array.isArray(sd.exclude) ? sd.exclude : []).map((s) => String(s).toLowerCase()));
  // Claudinite's own repo — what a member's stamped ref is measured against. Named
  // rather than inferred from the ref, because a ref tells you nothing about where
  // it came from; defaulted so no existing sheepdog config has to change.
  const canonRepo = String(sd.canonRepo ?? `${owner}/Claudinite`);
  // How far behind is too far. Not a hard number in code: a fleet whose members
  // legitimately go quiet for longer raises it rather than living with false alarms.
  const raw = Number(sd.staleDays);
  const staleDays = Number.isFinite(raw) && raw > 0 ? raw : 14;
  return { owner, exclude, canonRepo, staleDays };
}

