// Post-hoc enforcement of a task's declared outcome ceiling (per-project-scheduling
// DESIGN §1, §5.5). The executor runs this in code AFTER the subagent finishes:
// the outcome is a ceiling enforced, not merely requested in prose, so a `none`
// task that opened a PR — or an `open-pr` task that merged one — fails the run
// and converges to needs-human. "No change" is always legal.
//
// Pushes to non-default branches (e.g. the conversation-logs prune) are outside
// the PR taxonomy (DESIGN §1) and are not judged here — the caller passes only
// what the task did to PULL REQUESTS.

import { OUTCOMES } from './task-contract.mjs';

// Verify what a task actually did against its declared ceiling.
//   outcome    — the task's declared ceiling ('none' | 'open-pr' | 'merged-pr')
//   openedPr   — did the run open a pull request?
//   mergedPr   — did the run merge (or arm auto-merge on) a pull request?
// Returns { ok, violation } — violation is null when within the ceiling.
export function verifyOutcome({ outcome, openedPr = false, mergedPr = false }) {
  if (!OUTCOMES.includes(outcome)) {
    return { ok: false, violation: `unknown outcome ceiling "${outcome}"` };
  }
  // Merging implies a PR exists; treat a merge as also having opened one so a
  // caller that only reports mergedPr is still judged correctly.
  const opened = openedPr || mergedPr;

  if (outcome === 'none' && opened) {
    return { ok: false, violation: 'a "none" task must not open or merge a pull request' };
  }
  if (outcome === 'open-pr' && mergedPr) {
    return { ok: false, violation: 'an "open-pr" task must not merge a pull request' };
  }
  return { ok: true, violation: null };
}
// The pre-agent preprocessing stage (agent-preprocessing DESIGN §3). The
// scheduler runs a task's declared `agent_preprocessing` command as a SUBPROCESS
// before any agent starts — deterministic code work, Action-side, over the one
// sanctioned non-MCP surface (the Action GITHUB_TOKEN, inherited in `env`).
//
// The subprocess is the scheduler's child, so its `agent_preprocessing_timeout`
// is a HARD kill: a manual timer SIGKILLs an overrun and the run is reported
// failed. Its cwd is the TASK directory, so a declared `node worker.mjs` resolves
// to the script beside task.mjs (the containment the contract enforces); the repo
// root and slot context are handed in via CLAUDINITE_* env so the worker can act
// on the whole repo. Nothing the subprocess prints is threaded into the agent —
// preprocessing communicates only through the repository (DESIGN §3).

import { spawn } from 'node:child_process';
import { existsSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';

// Run `command` as a subprocess bounded by `timeoutSeconds`. Resolves (never
// rejects) with { ok, timedOut, code, signal, stdout, stderr }: `ok` is a clean
// zero exit that did not time out. `taskDir` is the cwd; `env` is the full
// environment the child inherits (the caller injects GITHUB_TOKEN + CLAUDINITE_*).
export function runPreprocessing(command, { taskDir, env, timeoutSeconds }) {
  return new Promise((resolve) => {
    const child = spawn(command, { cwd: taskDir, env, shell: true });
    let stdout = '';
    let stderr = '';
    let timedOut = false;
    const timer = setTimeout(() => {
      timedOut = true;
      child.kill('SIGKILL'); // the hard kill — no grace period past the declared bound
    }, timeoutSeconds * 1000);

    child.stdout?.on('data', (d) => { stdout += d; });
    child.stderr?.on('data', (d) => { stderr += d; });
    // A spawn error (command not found, etc.) is a failure, not a throw.
    child.on('error', (e) => {
      clearTimeout(timer);
      resolve({ ok: false, timedOut, code: null, signal: null, stdout, stderr: `${stderr}${e.message}` });
    });
