    ...parseLogName(name),
    counts: countEntries(parseEntries(git(root, ['show', `${found.tip}:${name}`])), mounted),
  }));

  const path = join(root, USAGE_PATH);
  let prior = {};
  try { prior = JSON.parse(readFileSync(path, 'utf8')); } catch { /* first fold */ }
  const today = new Date().toISOString().slice(0, 10);
  const folded = foldUsage({ files, prior, today });
  const text = `${JSON.stringify(folded, null, 2)}\n`;

  const current = existsSync(path) ? readFileSync(path, 'utf8') : null;
  const attributes = withMergeAttribute(
    existsSync(join(root, '.gitattributes')) ? readFileSync(join(root, '.gitattributes'), 'utf8') : null,
  );
