+// Fetch the logs branch and return its capture files, newest-name-last. Returns null
+// when the branch does not exist — a repo that has never captured has nothing to
+// fold, which is a clean no-op rather than a failure.
+function logFiles(root, token, repo) {
+  const remote = token ? `https://x-access-token:${token}@github.com/${repo}.git` : 'origin';
+  const heads = git(root, ['ls-remote', '--heads', remote, BRANCH]).trim();
+  if (!heads) return null;
+  git(root, ['fetch', '--quiet', remote, BRANCH]);
+  const tip = git(root, ['rev-parse', 'FETCH_HEAD']).trim();
+  const names = git(root, ['ls-tree', '--name-only', tip]).split('\n').filter(Boolean);
+  return { tip, names: names.filter((n) => parseLogName(n) !== null).sort() };
+}
+
+// --- delivery -----------------------------------------------------------------
+
+async function enableAutoMerge(token, pullRequestId) {
+  const query = 'mutation($id:ID!){enablePullRequestAutoMerge(input:{pullRequestId:$id,mergeMethod:SQUASH}){pullRequest{id}}}';
+  const res = await fetch(`${API}/graphql`, {
+    method: 'POST',
+    headers: { authorization: `Bearer ${token}`, 'content-type': 'application/json' },
+    body: JSON.stringify({ query, variables: { id: pullRequestId } }),
+  });
