// The default branch's remote tip, fetched into this checkout's object store. Read
// from the REMOTE, not from HEAD: the scheduler shares one checkout across every due
// task, so HEAD is whatever the last task left behind.
function baseTipSha(root, remote, base) {
  git(root, ['fetch', '--quiet', remote, base]);
  return git(root, ['rev-parse', 'FETCH_HEAD']).trim();
}

