+    method: 'POST',
+    headers: { authorization: `Bearer ${token}`, 'content-type': 'application/json' },
+    body: JSON.stringify({ query, variables: { id: pullRequestId } }),
+  });
+  const json = await res.json().catch(() => null);
+  if (json?.errors?.length) throw new Error(json.errors[0].message);
+}
+
+// A GENERATED file wants a `merge=ours` .gitattributes entry so a conflicting merge
+// resolves by re-running the generator rather than by hand (the canon's
+// GENERATED-file discipline, and the `generated-merge-driver` check that enforces
+// it). Written once, alongside the file it is about. Exported for the tests.
+export const MERGE_ATTR = 'usage.GENERATED.json merge=ours';
+export function withMergeAttribute(current) {
+  const text = current ?? '';
+  if (text.split('\n').some((l) => l.trim() === MERGE_ATTR)) return null; // already declared
+  return (text && !text.endsWith('\n') ? `${text}\n` : text) + `${MERGE_ATTR}\n`;
+}
+
+// Deliver the regenerated aggregate on its own run-stamped branch, arming
+// auto-merge. Every write goes through git PLUMBING against the fetched base tip —
+// the checkout's HEAD, index and working tree are never touched. That is not
+// fastidiousness: the scheduler runs every due task in ONE checkout, so a task that
+// checks a branch out hands the next task a tree it did not expect (baselining is
+// already building its own maintenance branch in there).
+//
+// Reuses an open fold PR by head-branch prefix so a fold that runs before the
+// previous day's PR merged updates that PR instead of stacking a second one — and
+// force-pushes, because the file is fully regenerated from the base every run.
+async function deliver(root, repo, base, token, stamp, contents) {
+  const { json: pulls } = await gh(token, `/repos/${repo}/pulls?state=open&per_page=100`);
+  let pr = (Array.isArray(pulls) ? pulls : []).find((p) => p.head?.ref?.startsWith(`${PR_BRANCH_PREFIX}/`));
+  const reuse = Boolean(pr);
+  const branch = reuse ? pr.head.ref : `${PR_BRANCH_PREFIX}/${stamp}`;
+  const remote = `https://x-access-token:${token}@github.com/${repo}.git`;
+
+  // Build the commit in a THROWAWAY index seeded from the base tip, so the tree we
+  // push is "the base branch plus exactly these files" whatever the checkout holds.
+  const baseTip = baseTipSha(root, remote, base);
+  const index = join(tmpdir(), `claudinite-usage-fold-${process.pid}.index`);
+  const plumb = (args, opts) => git(root, args, { ...opts, env: { ...process.env, GIT_INDEX_FILE: index } });
+  try {
+    plumb(['read-tree', baseTip]);
+    for (const [path, text] of Object.entries(contents)) {
+      const blob = git(root, ['hash-object', '-w', '--stdin'], { input: text }).trim();
+      plumb(['update-index', '--add', '--cacheinfo', `100644,${blob},${path}`]);
+    }
+    const tree = plumb(['write-tree']).trim();
+    const commit = git(root, [
+      '-c', 'user.name=claudinite[bot]', '-c', 'user.email=claudinite@users.noreply.github.com',
+      'commit-tree', tree, '-p', baseTip, '-m', 'Claudinite: fold skill-usage metrics',
+    ]).trim();
+    git(root, ['push', '--quiet', '--force', remote, `${commit}:refs/heads/${branch}`]);
+  } finally { rmSync(index, { force: true }); }
+
+  if (!reuse) {
+    ({ json: pr } = await gh(token, `/repos/${repo}/pulls`, {
+      method: 'POST',
+      body: {
+        head: branch,
+        base,
+        title: 'Claudinite: skill-usage fold',
+        body: [
+          `Regenerated \`${USAGE_PATH}\` from this repo's captured conversation logs.`,
+          '',
+          'Day rows are recomputed from scratch every run from the logs still inside the',
+          'retention window; week rows are appended once, past the `foldedThrough` watermark.',
+          'A byte-identical recompute opens no PR at all. Machine-written — never hand-edit it.',
+        ].join('\n'),
+      },
+    }));
+  }
+  // Best effort, and re-asserted every run: a repo that had auto-merge disabled when
+  // the PR was opened would otherwise leave it sitting open forever.
+  if (pr?.node_id) await enableAutoMerge(token, pr.node_id).catch(() => {});
+  return { branch, number: pr?.number ?? null, reused: reuse };
+}
+
+// --- main ---------------------------------------------------------------------
+
+export async function main() {
+  const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
+  const repo = process.env.CLAUDINITE_REPO || process.env.GITHUB_REPOSITORY;
+  const token = process.env.GITHUB_TOKEN;
+  const base = process.env.CLAUDINITE_DEFAULT_BRANCH || 'main';
+  if (!repo) throw new Error('CLAUDINITE_REPO / GITHUB_REPOSITORY is not set (owner/repo)');
+  if (!token) throw new Error('GITHUB_TOKEN is not set — the fold cannot read the logs branch or deliver its PR');
+
+  const found = logFiles(root, token, repo);
+  if (found === null) { log(`no ${BRANCH} branch — nothing captured yet, nothing to fold`); return; }
+
+  let config = {};
+  try { config = JSON.parse(readFileSync(join(root, '.claudinite-checks.json'), 'utf8')); } catch { /* no declaration */ }
+  const mounted = await mountedSkillNames(root, config);
+
+  const files = found.names.map((name) => ({
+    ...parseLogName(name),
+    counts: countEntries(parseEntries(git(root, ['show', `${found.tip}:${name}`])), mounted),
+  }));
+
+  // The prior state is read from the BASE TIP, never from the working tree: the
+  // checkout may be sitting on another task's branch, and the base is the only
+  // authority on what has already been folded. A fold PR still open when the next
+  // run fires is simply rebuilt from the base — the days recompute statelessly and
+  // the watermark advances from the same place, so nothing is ever counted twice.
+  const remote = `https://x-access-token:${token}@github.com/${repo}.git`;
+  const baseTip = baseTipSha(root, remote, base);
+  const readAtBase = (path) => {
+    try { return git(root, ['show', `${baseTip}:${path}`]); } catch { return null; }
+  };
+
+  let prior = {};
+  try { prior = JSON.parse(readAtBase(USAGE_PATH) ?? '{}'); } catch { /* unparsable → refold from scratch */ }
+  const today = new Date().toISOString().slice(0, 10);
+  const folded = foldUsage({ files, prior, today });
+  const text = `${JSON.stringify(folded, null, 2)}\n`;
+
+  const current = readAtBase(USAGE_PATH);
+  const attributes = withMergeAttribute(readAtBase('.gitattributes'));
+  if (current === text && attributes === null) {
+    log(`${files.length} capture file(s) folded — recompute is byte-identical, nothing to deliver`);
+    return;
+  }
+
+  const pr = await deliver(root, repo, base, token, today, {
+    [USAGE_PATH]: text,
+    ...(attributes !== null ? { '.gitattributes': attributes } : {}),
+  });
+  log(`${files.length} capture file(s) folded through ${folded.foldedThrough ?? '(nothing closed yet)'} — `
+    + `${pr.reused ? 'updated' : 'opened'} PR ${pr.number !== null ? `#${pr.number}` : `on ${pr.branch}`}`);
+}
+
+// Run only when invoked directly (the scheduler's `node worker.mjs`), never on import.
+if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
+  main().catch((e) => { console.error(`usage-fold failed: ${e.message}`); process.exit(1); });
+}

