+  encoding: 'utf8',
+  // A generated file can be large, and a `git show` of one easily tops spawn's
+  // default 1 MiB buffer — which fails as a truncated read, not as an error.
+  maxBuffer: 256 * 1024 * 1024,
+  stdio: ['ignore', 'pipe', 'pipe'],
+  ...opts,
+});
+
